import subprocess
def eff(s):
    # s without newline
    p=subprocess.run(["./executable","--padding","0"], input=(s+"\n").encode('utf-8'), stdout=subprocess.PIPE)
    out=p.stdout.decode().strip()
    # compute width as earlier: sum
    if not out:
        return 0
    width=0
    for i,ch in enumerate(out):
        code=ord(ch)-0x2800
        if i==len(out)-1:
            # last char
            if code==0:
                width+=2
            elif code in (1,8):
                width+=1
            elif code==9:
                width+=2
            else:
                # for single row, only those 4 possible, but for multi-dot rows more possibilities
                # For single row, code can be 0,1,8,9
                width+=2 if code==9 or code==0 else 1
        else:
            # non-last char always 2? Actually for single row, blank char is 2, '⠉' is 2
            width+=2
    return width, out

tests=["あ","aあ","あb","bあ","あa","aあb","bあa","ああ","aああ","ああa","あaあ","ab","a b","あ b","a あ","aあ b","あ   b"]
for t in tests:
    w,out=eff(t)
    print(f"{t!r} chars {len(t)} bytes {len(t.encode('utf-8'))} => width {w} out {out!r}")

