    #[arg(short='H', long="horizontal-scale", default_value="1.0")]
    horizontal_scale: f64,
    #[arg(short='V', long="vertical-scale", default_value="1.0")]
    vertical_scale: f64,
    #[arg(long="padding")]
    padding: Option<usize>,
    #[arg(long="encoding", default_value="utf8-lossy", value_parser=clap::builder::PossibleValuesParser::new(["utf8-lossy","utf8"]))]
    encoding: String,
    #[arg(value_name="FILE")]
    file: Option<String>,
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    Completion { shell: Shell },
}

#[derive(Clone, ValueEnum)]
enum Shell {
    Bash,
    Elvish,
    Fish,
    Powershell,
    Zsh,
}

fn main() {
    let cli = Cli::parse();
    if let Some(Commands::Completion { shell }) = cli.command {
        let mut cmd = Cli::command();
        let bin_name = "code-minimap";
        match shell {
            Shell::Bash => generate(clap_complete::Shell::Bash, &mut cmd, bin_name, &mut std::io::stdout()),
            Shell::Elvish => generate(clap_complete::Shell::Elvish, &mut cmd, bin_name, &mut std::io::stdout()),
            Shell::Fish => generate(clap_complete::Shell::Fish, &mut cmd, bin_name, &mut std::io::stdout()),
            Shell::Powershell => generate(clap_complete::Shell::PowerShell, &mut cmd, bin_name, &mut std::io::stdout()),
            Shell::Zsh => generate(clap_complete::Shell::Zsh, &mut cmd, bin_name, &mut std::io::stdout()),
        }
    }
}
