fn rust_lines(text: &str) -> Vec<String> {
    if text.is_empty() {
        return Vec::new();
    }
    let mut parts: Vec<&str> = text.split('\n').collect();
    if text.ends_with('\n') {
        parts.pop();
    }
    let mut res = Vec::with_capacity(parts.len());
    for part in parts {
        let mut p = part;
        if p.ends_with('\r') {
            p = &p[..p.len()-1];
        }
        res.push(p.to_string());
    }
    res
}

fn compute_group_info(lines: &[String], hs: f64) -> (usize, Option<usize>, Option<usize>) {
    let mut first_bytes: Vec<usize> = Vec::new();
    let mut last_bytes: Vec<usize> = Vec::new();

    for line in lines {
        let mut byte_offset = 0usize;
        let mut char_byte_offsets: Vec<usize> = Vec::new();
        let mut chars: Vec<char> = Vec::new();
        for ch in line.chars() {
            char_byte_offsets.push(byte_offset);
            chars.push(ch);
            byte_offset += ch.len_utf8();
        }
        let mut first_off: Option<usize> = None;
        let mut last_off: Option<usize> = None;
        for (idx, ch) in chars.iter().enumerate() {
            if !ch.is_whitespace() {
                if first_off.is_none() {
                    first_off = Some(char_byte_offsets[idx]);
                }
                last_off = Some(char_byte_offsets[idx]);
            }
        }
        if let (Some(f), Some(l)) = (first_off, last_off) {
            first_bytes.push(f);
            last_bytes.push(l);
        }
    }

    if first_bytes.is_empty() {
        let w = (1.0 * hs).floor() as usize;
        return (w, None, None);
    }

    let first_byte = *first_bytes.iter().min().unwrap();
    let last_byte = *last_bytes.iter().max().unwrap();
    let w = ((last_byte + 1) as f64 * hs).floor() as usize;
    let ds = (first_byte as f64 * hs).floor() as usize;
    let de = ((last_byte + 1) as f64 * hs).floor() as usize;
    let de = if de == 0 { None } else { Some(de - 1) };
    if let Some(de_val) = de {
        if ds > de_val {
            return (w, None, None);
        } else {
            return (w, Some(ds), Some(de_val));
        }
    } else {
        return (w, None, None);
    }
}

fn minimap(text: &str, hs: f64, vs: f64, padding: Option<usize>) -> String {
    let lines = rust_lines(text);
    let l = lines.len();
    if l == 0 {
        return String::new();
    }
    let vs_capped = vs.min(1.0);

    let mut scaled_rows: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for i in 0..l {
        let d = (i as f64 * vs_capped).floor() as usize;
        scaled_rows.entry(d).or_default().push(i);
    }

    let total_distinct = *scaled_rows.keys().max().unwrap() + 1;
    let num_braille_rows = (total_distinct + 3) / 4;

    let mut output_lines: Vec<String> = Vec::with_capacity(num_braille_rows);

    for br in 0..num_braille_rows {
        let mut scaled_in_br: Vec<(usize, usize, Vec<usize>)> = Vec::new();
        for r in 0..4 {
            let d = br * 4 + r;
            if let Some(indices) = scaled_rows.get(&d) {
                scaled_in_br.push((d, r, indices.clone()));
            }
        }
        if scaled_in_br.is_empty() {
            output_lines.push(String::new());
            continue;
        }

        let mut scaled_info: BTreeMap<usize, (usize, Option<usize>, Option<usize>, usize)> = BTreeMap::new();
        let mut max_w = 0usize;
        for (d, r, line_indices) in &scaled_in_br {
            let group_lines: Vec<String> = line_indices.iter().map(|&i| lines[i].clone()).collect();
            let (w, ds, de) = compute_group_info(&group_lines, hs);
            if w > max_w {
                max_w = w;
            }
            scaled_info.insert(*d, (w, ds, de, *r));
        }

        let num_chars = if max_w == 0 { 0 } else { (max_w + 1) / 2 };

        let mut char_bits = vec![0u32; num_chars];

        for (d, r, _line_indices) in &scaled_in_br {
            if let Some((_, ds_opt, de_opt, _)) = scaled_info.get(d) {
                if let (Some(ds), Some(de)) = (ds_opt, de_opt) {
                    for s in *ds..=*de {
                        if s >= max_w {
                            continue;
                        }
                        let ci = s / 2;
                        let subcol = s % 2;
                        let bit = match (r, subcol) {
                            (0, 0) => 1,
                            (1, 0) => 2,
                            (2, 0) => 4,
                            (3, 0) => 64,
                            (0, 1) => 8,
                            (1, 1) => 16,
                            (2, 1) => 32,
                            (3, 1) => 128,
                            _ => 0,
                        };
                        if ci < char_bits.len() {
                            char_bits[ci] |= bit;
                        }
                    }
                }
            }
        }

        let mut braille_str = String::with_capacity(num_chars);
        for bits in char_bits {
            braille_str.push(char::from_u32(0x2800 + bits).unwrap());
        }

        if let Some(pad) = padding {
            if braille_str.chars().count() < pad {
                let diff = pad - braille_str.chars().count();
                braille_str.extend(std::iter::repeat(' ').take(diff));
            }
        }

        output_lines.push(braille_str);
    }

    let mut result = String::new();
    for line in output_lines.iter() {
        result.push_str(line);
        result.push('\n');
    }
    result
}

