actions.command:
cd /workspace
# The issue is Command::new requires 'static lifetime for bin name? Actually clap_builder's Str is owned, but it requires 'static? Let's see error: borrowed value does not live long enough, requires 'static. So we need to leak bin_name.

# Use Box::leak

cat > src/main.rs <<'RS'
use clap_builder::{Command, Arg, value_parser, ValueHint, ArgAction};
use std::io::{Read, Write};
use std::collections::BTreeMap;

fn get_bin_name() -> String {
    let arg0 = std::env::args().next().unwrap_or_else(|| "code-minimap".to_string());
    let path = std::path::Path::new(&arg0);
    if let Some(file_name) = path.file_name() {
        file_name.to_string_lossy().to_string()
    } else {
        arg0
    }
}

fn build_cmd() -> Command {
    let bin_name = get_bin_name();
    let bin_static: &'static str = Box::leak(bin_name.into_boxed_str());
    Command::new(bin_static)
        .version("0.6.8")
        .disable_version_flag(true)
        .disable_help_flag(true)
        .disable_help_subcommand(true)
        .about("A high performance code minimap generator")
        .arg(Arg::new("horizontal-scale").short('H').long("horizontal-scale").value_name("HSCALE").default_value("1.0").help("Specify horizontal scale factor"))
        .arg(Arg::new("vertical-scale").short('V').long("vertical-scale").value_name("VSCALE").default_value("1.0").help("Specify vertical scale factor"))
        .arg(Arg::new("padding").long("padding").value_name("PADDING").value_parser(value_parser!(usize)).help("Specify padding width"))
        .arg(Arg::new("encoding").long("encoding").value_name("ENCODING").default_value("utf8-lossy").value_parser(["utf8-lossy","utf8"]).help("Specify input encoding"))
        .arg(Arg::new("version").long("version").action(ArgAction::Version).help("Print version"))
        .arg(Arg::new("help").short('h').long("help").action(ArgAction::Help).help("Print help"))
        .arg(Arg::new("file").value_name("FILE").value_hint(ValueHint::FilePath).help("File to read"))
        .subcommand(Command::new("completion").about("Generate shell completion file").arg(Arg::new("shell").value_name("SHELL").required(true).value_parser(["bash","elvish","fish","powershell","zsh"]).help("Target shell name")))
        .subcommand(Command::new("help").about("Print this message or the help of the given subcommand(s)").arg(Arg::new("command").value_name("COMMAND").num_args(0..).help("Print help for the subcommand(s)")))
}

fn main() {
    let mut cmd = build_cmd();

    let matches = cmd.clone().get_matches();

    if let Some(sub) = matches.subcommand_matches("completion") {
        let shell = sub.get_one::<String>("shell").unwrap().as_str();
        match shell {
            "bash" => {
                print!("{}", BASH_COMPLETION);
            }
            "elvish" => {
                print!("{}", ELVISH_COMPLETION);
            }
            "fish" => {
                print!("{}", FISH_COMPLETION);
            }
            "powershell" => {
                print!("{}", POWERSHELL_COMPLETION);
            }
            "zsh" => {
                print!("{}", ZSH_COMPLETION);
            }
            _ => {}
        }
        return;
    }

    if let Some(help_matches) = matches.subcommand_matches("help") {
        if let Some(cmds) = help_matches.get_many::<String>("command") {
            let cmds_vec: Vec<&String> = cmds.collect();
            if cmds_vec.is_empty() {
                let _ = cmd.print_help();
                println!();
                return;
            }
            let subcmd_name = cmds_vec[0].as_str();
            if subcmd_name == "completion" {
                let bin_name = get_bin_name();
                let comp_bin_str = format!("{} completion", bin_name);
                let comp_bin: &'static str = Box::leak(comp_bin_str.into_boxed_str());
                let mut comp_cmd = Command::new(comp_bin)
                    .about("Generate shell completion file")
                    .arg(Arg::new("shell").value_name("SHELL").required(true).value_parser(["bash","elvish","fish","powershell","zsh"]).help("Target shell name"))
                    .arg(Arg::new("help").short('h').long("help").action(ArgAction::Help).help("Print help"));
                let _ = comp_cmd.print_help();
                println!();
                return;
            } else if subcmd_name == "help" {
                let bin_name = get_bin_name();
                let help_bin_str = format!("{} help", bin_name);
                let help_bin: &'static str = Box::leak(help_bin_str.into_boxed_str());
                let mut h_cmd = Command::new(help_bin)
                    .about("Print this message or the help of the given subcommand(s)")
                    .arg(Arg::new("command").value_name("COMMAND").num_args(0..).help("Print help for the subcommand(s)"));
                let _ = h_cmd.print_help();
                println!();
                return;
            } else {
                let _ = cmd.print_help();
                println!();
                return;
            }
        } else {
            let _ = cmd.print_help();
            println!();
            return;
        }
    }

    let hscale_str = matches.get_one::<String>("horizontal-scale").unwrap();
    let vscale_str = matches.get_one::<String>("vertical-scale").unwrap();

    let hscale: f64 = match hscale_str.parse() {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--horizontal-scale <HSCALE>': invalid float literal\n\nFor more information, try '--help'.", hscale_str);
            std::process::exit(2);
        }
    };
    let vscale: f64 = match vscale_str.parse() {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--vertical-scale <VSCALE>': invalid float literal\n\nFor more information, try '--help'.", vscale_str);
            std::process::exit(2);
        }
    };

    let padding: Option<usize> = matches.get_one::<usize>("padding").copied();

    let encoding = matches.get_one::<String>("encoding").unwrap().as_str();

    let input_bytes: Vec<u8> = if let Some(file) = matches.get_one::<String>("file") {
        match std::fs::read(file) {
            Ok(b) => b,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    eprintln!("code-minimap: No such file or directory (os error 2)");
                } else {
                    eprintln!("code-minimap: {} (os error {})", e, e.raw_os_error().unwrap_or(1));
                }
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        std::io::stdin().read_to_end(&mut buf).unwrap();
        buf
    };

    let text: String = match encoding {
        "utf8" => {
            match String::from_utf8(input_bytes) {
                Ok(s) => s,
                Err(_) => {
                    eprintln!("code-minimap: stream did not contain valid UTF-8");
                    std::process::exit(1);
                }
            }
        }
        "utf8-lossy" => {
            String::from_utf8_lossy(&input_bytes).into_owned()
        }
        _ => unreachable!(),
    };

    let output = minimap(&text, hscale, vscale, padding);
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = handle.write_all(output.as_bytes());
}

fn rust_lines(text: &str) -> Vec<String> {
    if text.is_empty() {
        return Vec::new();
    }
    let mut parts: Vec<&str> = text.split('\n').collect();
    if text.ends_with('\n') {
        parts.pop();
    }
    let mut res = Vec::with_capacity(parts.len());
    for part in parts {
        let mut p = part;
        if p.ends_with('\r') {
            p = &p[..p.len()-1];
        }
        res.push(p.to_string());
    }
    res
}

fn compute_group_info(lines: &[String], hs: f64) -> (usize, Option<usize>, Option<usize>) {
    let mut first_bytes: Vec<usize> = Vec::new();
    let mut last_bytes: Vec<usize> = Vec::new();

    for line in lines {
        let mut byte_offset = 0usize;
        let mut char_byte_offsets: Vec<usize> = Vec::new();
        let mut chars: Vec<char> = Vec::new();
        for ch in line.chars() {
            char_byte_offsets.push(byte_offset);
            chars.push(ch);
            byte_offset += ch.len_utf8();
        }
        let mut first_off: Option<usize> = None;
        let mut last_off: Option<usize> = None;
        for (idx, ch) in chars.iter().enumerate() {
            if !ch.is_whitespace() {
                if first_off.is_none() {
                    first_off = Some(char_byte_offsets[idx]);
                }
                last_off = Some(char_byte_offsets[idx]);
            }
        }
        if let (Some(f), Some(l)) = (first_off, last_off) {
            first_bytes.push(f);
            last_bytes.push(l);
        }
    }

    if first_bytes.is_empty() {
        let w = (1.0 * hs).floor() as usize;
        return (w, None, None);
    }

    let first_byte = *first_bytes.iter().min().unwrap();
    let last_byte = *last_bytes.iter().max().unwrap();
    let w = ((last_byte + 1) as f64 * hs).floor() as usize;
    let ds = (first_byte as f64 * hs).floor() as usize;
    let de = ((last_byte + 1) as f64 * hs).floor() as usize;
    let de = if de == 0 { None } else { Some(de - 1) };
    if let Some(de_val) = de {
        if ds > de_val {
            return (w, None, None);
        } else {
            return (w, Some(ds), Some(de_val));
        }
    } else {
        return (w, None, None);
    }
}

fn minimap(text: &str, hs: f64, vs: f64, padding: Option<usize>) -> String {
    let lines = rust_lines(text);
    let l = lines.len();
    if l == 0 {
        return String::new();
    }
    let vs_capped = vs.min(1.0);

    let mut scaled_rows: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for i in 0..l {
        let d = (i as f64 * vs_capped).floor() as usize;
        scaled_rows.entry(d).or_default().push(i);
    }

    let total_distinct = *scaled_rows.keys().max().unwrap() + 1;
    let num_braille_rows = (total_distinct + 3) / 4;

    let mut output_lines: Vec<String> = Vec::with_capacity(num_braille_rows);

    for br in 0..num_braille_rows {
        let mut scaled_in_br: Vec<(usize, usize, Vec<usize>)> = Vec::new();
        for r in 0..4 {
            let d = br * 4 + r;
            if let Some(indices) = scaled_rows.get(&d) {
                scaled_in_br.push((d, r, indices.clone()));
            }
        }
        if scaled_in_br.is_empty() {
            output_lines.push(String::new());
            continue;
        }

        let mut scaled_info: BTreeMap<usize, (usize, Option<usize>, Option<usize>, usize)> = BTreeMap::new();
        let mut max_w = 0usize;
        for (d, r, line_indices) in &scaled_in_br {
            let group_lines: Vec<String> = line_indices.iter().map(|&i| lines[i].clone()).collect();
            let (w, ds, de) = compute_group_info(&group_lines, hs);
            if w > max_w {
                max_w = w;
            }
            scaled_info.insert(*d, (w, ds, de, *r));
        }

        let num_chars = if max_w == 0 { 0 } else { (max_w + 1) / 2 };

        let mut char_bits = vec![0u32; num_chars];

        for (d, r, _line_indices) in &scaled_in_br {
            if let Some((_, ds_opt, de_opt, _)) = scaled_info.get(d) {
                if let (Some(ds), Some(de)) = (ds_opt, de_opt) {
                    for s in *ds..=*de {
                        if s >= max_w {
                            continue;
                        }
                        let ci = s / 2;
                        let subcol = s % 2;
                        let bit = match (r, subcol) {
                            (0, 0) => 1,
                            (1, 0) => 2,
                            (2, 0) => 4,
                            (3, 0) => 64,
                            (0, 1) => 8,
                            (1, 1) => 16,
                            (2, 1) => 32,
                            (3, 1) => 128,
                            _ => 0,
                        };
                        if ci < char_bits.len() {
                            char_bits[ci] |= bit;
                        }
                    }
                }
            }
        }

        let mut braille_str = String::with_capacity(num_chars);
        for bits in char_bits {
            braille_str.push(char::from_u32(0x2800 + bits).unwrap());
        }

        if let Some(pad) = padding {
            if braille_str.chars().count() < pad {
                let diff = pad - braille_str.chars().count();
                braille_str.extend(std::iter::repeat(' ').take(diff));
            }
        }

        output_lines.push(braille_str);
    }

    let mut result = String::new();
    for line in output_lines.iter() {
        result.push_str(line);
        result.push('\n');
    }
    result
}

