        b=0
        for ch in line:
            byte_offsets.append(b)
            b+=len(ch.encode('utf-8'))
        first_off=None
        last_off=None
        for idx,ch in enumerate(line):
            if not ch.isspace():
                if first_off is None:
                    first_off=byte_offsets[idx]
                last_off=byte_offsets[idx]
        if first_off is not None:
            first_bytes.append(first_off)
            last_bytes.append(last_off)
    if not first_bytes:
        w=math.floor(1*hs+1e-9)
        return w, None, None
    first_byte=min(first_bytes)
    last_byte=max(last_bytes)
    w=math.floor((last_byte+1)*hs+1e-9)
    ds=math.floor(first_byte*hs+1e-9)
    de=math.floor((last_byte+1)*hs+1e-9)-1
    if de==0:
        return w, None, None
    de = de
    if ds>de:
        return w, None, None
    return w, ds, de

