}

fn main() {
    let bin_name = get_bin_name();
    let mut cmd = build_cmd();

    let matches = match cmd.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // For help, clap will have already printed help and exited? Actually with Help action, it prints help and exits with code 0 via our custom? No, Help action does print_help and exit.
            // But we disabled help subcommand, so need to handle.
            // For errors, print and exit
            let _ = e.print();
