import subprocess, math, random

def rust_lines(text):
    if text=="":
        return []
    parts=text.split("\n")
    if text.endswith("\n"):
        parts=parts[:-1]
    res=[]
    for part in parts:
        if part.endswith("\r"):
            part=part[:-1]
        res.append(part)
    return res

def compute_group_info(lines, hs):
    first_bytes=[]
    last_bytes=[]
    for line in lines:
        byte_offsets=[]
        b=0
        for ch in line:
            byte_offsets.append(b)
            b+=len(ch.encode('utf-8'))
        first_off=None
        last_off=None
        for idx,ch in enumerate(line):
            if not ch.isspace():
                if first_off is None:
                    first_off=byte_offsets[idx]
                last_off=byte_offsets[idx]
        if first_off is not None:
            first_bytes.append(first_off)
            last_bytes.append(last_off)
    if not first_bytes:
        w=math.floor(1*hs+1e-9)
        return w, None, None
    first_byte=min(first_bytes)
    last_byte=max(last_bytes)
    w=math.floor((last_byte+1)*hs+1e-9)
    ds=math.floor(first_byte*hs+1e-9)
    de_f=math.floor((last_byte+1)*hs+1e-9)
    if de_f==0:
        return w, None, None
    de=de_f-1
    if ds>de:
        return w, None, None
    return w, ds, de

def python_minimap(text, hs=1.0, vs=1.0, padding=None):
    lines=rust_lines(text)
    L=len(lines)
    if L==0:
        return ""
    vs_capped=min(vs,1.0)
    scaled_rows={}
    for i in range(L):
        d=math.floor(i*vs_capped+1e-9)
        scaled_rows.setdefault(d, []).append(i)
    total_distinct = max(scaled_rows.keys())+1
    num_braille_rows = (total_distinct+3)//4
    output=[]
    for br in range(num_braille_rows):
        scaled_in_br=[]
        for r in range(4):
            d=br*4+r
            if d in scaled_rows:
                scaled_in_br.append((d,r,scaled_rows[d]))
        if not scaled_in_br:
            output.append("")
            continue
        scaled_info={}
        max_w=0
        for d,r,idxs in scaled_in_br:
            gl=[lines[i] for i in idxs]
            w,ds,de = compute_group_info(gl, hs)
            if w>max_w:
                max_w=w
            scaled_info[d]=(w,ds,de,r)
        num_chars = 0 if max_w==0 else (max_w+1)//2
        bits=[0]*num_chars
        for d,r,idxs in scaled_in_br:
            w,ds,de,r = scaled_info[d]
            if ds is None:
                continue
            for s in range(ds, de+1):
                if s>=max_w:
                    continue
                ci=s//2
                sub=s%2
                if r==0 and sub==0:
                    b=1
                elif r==1 and sub==0:
                    b=2
                elif r==2 and sub==0:
                    b=4
                elif r==3 and sub==0:
                    b=64
                elif r==0 and sub==1:
                    b=8
                elif r==1 and sub==1:
                    b=16
                elif r==2 and sub==1:
                    b=32
                elif r==3 and sub==1:
                    b=128
                bits[ci]|=b
        s=""
        for bb in bits:
            s+=chr(0x2800+bb)
        if padding is not None and len(s)<padding:
            s+=" "*(padding-len(s))
        output.append(s)
    return "\n".join(output)+"\n" if output else ""

def rust_out(text, hs, vs, pad):
    args=["/workspace/executable","-H",str(hs),"-V",str(vs)]
    if pad is not None:
        args+=["--padding",str(pad)]
    p=subprocess.run(args, input=text.encode('utf-8'), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout.decode('utf-8','replace')

for _ in range(1000):
    L=random.randint(0,20)
    lines=[]
    for _ in range(L):
        cl=random.randint(0,10)
        s=""
        for _ in range(cl):
            c=random.choice(['a','a','a','a',' ',' ','b','\t','\r'])
            s+=c
        lines.append(s)
    text="\n".join(lines)
    if L>0 and random.random()<0.5:
        text+="\n"
    hs=random.choice([0.25,0.5,0.75,1.0,1.5,2.0,0.1,4.0])
    vs=random.choice([0.25,0.5,0.75,1.0,1.5,2.0,0.1,4.0])
    pad=random.choice([None,0,1,2,3,5,10])
    py=python_minimap(text, hs=hs, vs=vs, padding=pad)
    rs=rust_out(text, hs, vs, pad)
    if py!=rs:
        print(f"MISMATCH ascii {text!r} hs={hs} vs={vs} pad={pad}")
        print(f"py={py!r}")
        print(f"rs={rs!r}")
        break
else:
    print("1000 ascii random passed")

